/**
 * Show all programlinks links on clicking read more.
 *
 * @module     tool_catalogue/programlinks
 * @author     2022 Bas Brands <bas@moodle.com>
 * @copyright  2022 Moodle Pty Ltd <support@moodle.com>
 * @license    Moodle Workplace License, distribution is restricted, contact support@moodle.com
 */

import SELECTORS from './selectors';

const CLASSES = {
    HIDE: 'd-none',
};

/**
 * Displays all the availability information in case part of it is hidden.
 *
 * @param {Event} event the triggered event
 */
const showMoreHandler = (event) => {
    const triggerElement = event.target.closest(SELECTORS.actions.showMoreLink);
    if (triggerElement === null) {
        return;
    }
    const programLinks = triggerElement.closest(SELECTORS.regions.programLinks);
    programLinks.querySelectorAll('.' + CLASSES.HIDE).forEach(function(node) {
        node.classList.remove(CLASSES.HIDE);
    });

    triggerElement.classList.add(CLASSES.HIDE);
    event.preventDefault();
};

/**
 * Initialise the event lister for the showmore action on availability information.
 *
 * @method  init
 */
export const init = () => {
    const programLinks = document.querySelector(SELECTORS.regions.programLinks);
    const showMoreLink = programLinks.querySelector(SELECTORS.actions.showMoreLink);
    if (showMoreLink) {
        showMoreLink.addEventListener('click', showMoreHandler);
    }
};
